const json=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store'}});
export function database(env){if(!env.DB)throw Error('Database unavailable');return env.DB}
export async function handleRequest(request,env){
 const url=new URL(request.url);if(url.pathname!='/api/requests')return null;
 if(request.method!=='POST')return json({error:'Method not allowed'},405);
 if(request.headers.get('origin')&&request.headers.get('origin')!==url.origin)return json({error:'Virheellinen pyyntö.'},403);
 if(!request.headers.get('content-type')?.includes('application/json'))return json({error:'Virheellinen sisältö.'},415);
 if(Number(request.headers.get('content-length')||0)>16000)return json({error:'Pyyntö on liian pitkä.'},413);
 let data;try{const text=await request.text();if(text.length>16000)return json({error:'Pyyntö on liian pitkä.'},413);data=JSON.parse(text)}catch{return json({error:'Virheellinen pyyntö.'},400)}
 if(!data||typeof data!=='object'||Array.isArray(data))return json({error:'Virheellinen pyyntö.'},400);
 if(data.website)return json({error:'Pyyntöä ei voitu lähettää.'},400);
 const fields={registration:20,car:120,name:100,phone:30,email:254,service:100,message:2000,date:10,year:4};const clean={};
 for(const [key,max] of Object.entries(fields)){if(data[key]!=null&&typeof data[key]!=='string')return json({error:'Tarkista lomakkeen tiedot.'},400);clean[key]=(data[key]||'').trim();if(clean[key].length>max)return json({error:'Tarkista kenttien pituudet.'},400)}
 if(!['appointment','quote'].includes(data.type)||!data.consent||!['registration','name','phone','service'].every(key=>clean[key])||(clean.email&&!/^\S+@\S+\.\S+$/.test(clean.email))||!/^\+?[\d\s()\-]{5,30}$/.test(clean.phone)||!/^\d{4}-\d{2}-\d{2}$/.test(clean.date||'2000-01-01')||!/^\d{4}$/.test(clean.year||'2000')||!/^[-a-zA-Z0-9]{36}$/.test(data.id||''))return json({error:'Täytä pakolliset tiedot ja tarkista sähköposti sekä puhelinnumero.'},400);
 if(clean.year&&(Number(clean.year)<1900||Number(clean.year)>new Date().getFullYear()+1))return json({error:'Tarkista vuosimalli.'},400);
 if(clean.date&&(Number.isNaN(Date.parse(clean.date))||clean.date<new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Helsinki'}).format(new Date())))return json({error:'Valitse tuleva päivä.'},400);
 const reference='SC-'+data.id.replaceAll('-','').slice(0,10).toUpperCase();
 try{await database(env).prepare('INSERT INTO service_requests (id, reference, request_type, registration, car, year, service, preferred_date, customer_name, phone, email, message, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(id) DO NOTHING').bind(data.id,reference,data.type,clean.registration.toUpperCase(),clean.car,clean.year,clean.service,clean.date,clean.name,clean.phone,clean.email,clean.message,new Date().toISOString()).run();return json({reference},201)}catch(error){console.error('Request storage failed');return json({error:'Tallennus ei onnistunut. Tietosi ovat lomakkeella. Yritä hetken kuluttua uudelleen.'},503)}
}

const assets={"/app.js":{"type":"text/javascript","data":""},"/dates.js":{"type":"text/javascript","data":""},"/index.html":{"type":"text/html; charset=utf-8","data":""},"/motion.css":{"type":"text/css","data":""},"/motion.js":{"type":"text/javascript","data":""},"/polish.css":{"type":"text/css","data":""},"/red-car-hero.png":{"type":"image/png","data":""},"/site.js":{"type":"text/javascript","data":""},"/style.css":{"type":"text/css","data":""},"/suni-car-logo.png":{"type":"image/png","data":""},"/variation.css":{"type":"text/css","data":""}};
export default {async fetch(request,env){const response=await handleRequest(request,env);if(response)return response;const pathname=new URL(request.url).pathname;const asset=assets[pathname==="/"?"/index.html":pathname];if(!asset)return new Response("Not found",{status:404});if(!["GET","HEAD"].includes(request.method))return new Response("Method not allowed",{status:405});return new Response(request.method==="HEAD"?null:Uint8Array.from(atob(asset.data),c=>c.charCodeAt(0)),{headers:{"Content-Type":asset.type,"X-Content-Type-Options":"nosniff","Cache-Control":"no-cache"}})}};